  tmin = time_of_flight * 1e-6 - (iCHA_WIDTH * iELPEAK - iTOF_DELAY) * 1e-6;
  tmax = tmin + iTOF_CHA_RESOL * iCHA_WIDTH * 1e-6;
  printf("Time window:                   min=%g max=%g delay=%g tof-width=%g [ms]\n", tmin * 1000, tmax * 1000, iTOF_DELAY * 1e-3, (tmax - tmin) * 1000);

  char opt2[256];
  char opt1[256];
  char opt3[256];
  char optL[256];
  char optT[256];

  sprintf(opt2, "kxy limits=[0 5] bins=50, energy limits=[%g %g] bins=40, banana, parallel", (Ei - 20 < 0 ? 0 : Ei - 20), Ei + 20);
  sprintf(opt1, "angle limits=[0 180] bins=180, energy limits=[%g %g] bins=40, banana, parallel", (Ei - 20 < 0 ? 0 : Ei - 20), Ei + 20);
  sprintf(opt3, "user1 limits=[0.5,3.5] bins=9, lambda limits=[%g %g] bins=20, square, per cm2", 0.97 * lambda, 1.03 * lambda);
  sprintf(optL, "lambda limits=[%g %g] bins=50", lambda - dlambda, lambda + dlambda);
  sprintf(optT, "t slit limits=[%g %g]", tmin, tmax);

  // Components
  Progress_bar Origin AT (0, 0, 0) RELATIVE ABSOLUTE ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

  Source_gen VCS AT (0, 0, 0) RELATIVE Origin ROTATED (0, 0, 0) RELATIVE ABSOLUTE
