  Monochromator_curved Mono1 AT (0, 0, -LMM) RELATIVE Cradle ROTATED (0, A1 / 2, 0) RELATIVE Cradle
    REFLECT = "HOPG.rfl"
    TRANSMIT = "HOPG.trm"
    ZWIDTH = 0.054
    YHEIGHT = 0.029
    GAP = 0.001
    NH = 1
    NV = 7
    R0 = 1
    T0 = 1
    RV = RV
    DM = DM
    MOSAIC = mos
    EXTEND {
      if (SCATTERED) { monok_index = 1; }
    };

  Monochromator_curved Mono2 AT (0, 0, 0) RELATIVE Cradle ROTATED (0, A2 / 2, 0) RELATIVE Cradle
    REFLECT = "HOPG.rfl"
    TRANSMIT = "HOPG.trm"
    ZWIDTH = 0.054
    YHEIGHT = 0.029
    GAP = 0.001
    NH = 1
    NV = 7
    R0 = 1
    T0 = 1
    RV = RV
    DM = DM
    MOSAIC = mos
    EXTEND {
      if (SCATTERED) { monok_index = 2; }
    };

  Monochromator_curved Mono3 AT (0, 0, +LMM) RELATIVE Cradle ROTATED (0, A3 / 2, 0) RELATIVE Cradle
    REFLECT = "HOPG.rfl"
    TRANSMIT = "HOPG.trm"
    ZWIDTH = 0.054
    YHEIGHT = 0.029
    GAP = 0.001
    NH = 1
    NV = 7
    R0 = 1
    T0 = 1
    RV = RV
    DM = DM
    MOSAIC = mos
    EXTEND {
      if (SCATTERED) { monok_index = 3; }
    };

  Arm mono_out AT (0, 0, 0) RELATIVE Cradle ROTATED (0, A2cradle, 0) RELATIVE Cradle;

  Arm SuppPos AT (0, 0, LME - LCE - LCC) RELATIVE mono_out ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

  Monitor_nD Mon_SuppInL AT (0, 0, -0.07 - 0.002) RELATIVE SuppPos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    XWIDTH = 0.052
    YHEIGHT = 0.098
    OPTIONS = optL
    RESTORE_NEUTRON = 1;

  Monitor_nD Mon_SuppInT AT (0, 0, -0.07 - 0.001) RELATIVE SuppPos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    XWIDTH = 0.052
    YHEIGHT = 0.098
    BINS = iTOF_CHA_RESOL
    OPTIONS = optT
    RESTORE_NEUTRON = 1
    EXTEND {
      double Vi = sqrt(vx * vx + vy * vy + vz * vz);
      double ratio = PI * Frequency / iRATIO / atan(0.052 / 0.14);
      if (iRATIO && Vi) {
        double Tfermi = atan2(0.052, 0.14) / Frequency / PI;
        t = -(0.071 / Vi) + (rand01() - 0.5) * Tfermi;
        p *= 4 * atan2(0.052, 0.14) * RAD2DEG / 360;
      }
    };

  FermiChopper Suppressor AT (0, 0, 0) RELATIVE SuppPos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    PHASE = 0
    RADIUS = 0.07
    NU = Frequency / iRATIO
    NSLIT = 1
    R0 = 0
    LENGTH = 0.012
    EFF = 1
    XWIDTH = 0.052
    VERBOSE = 1
    YHEIGHT = 0.098
    WHEN (iRATIO > 0);

  Monitor_nD Mon_SuppOutT AT (0, 0, +0.07 + 0.001) RELATIVE SuppPos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    XWIDTH = 0.052
    YHEIGHT = 0.098
    BINS = iTOF_CHA_RESOL
    OPTIONS = "t slit limits=[-700e-6 700e-6]"
    RESTORE_NEUTRON = 1;

  Slit SlitFC AT (0, 0, LME - LCE - 0.041) RELATIVE mono_out ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    XWIDTH = 0.0441
    YHEIGHT = 0.0641;

  Arm FermiPos AT (0, 0, LME - LCE) RELATIVE mono_out ROTATED (0, 0, 0) RELATIVE ABSOLUTE;

  FermiChopper FermiM AT (0, 0, 0) RELATIVE FermiPos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    PHASE = iPHASE
    RADIUS = 0.04
    NU = Frequency
    NSLIT = 200.0
    R0 = 0.99
    Qc = (mFC < 1 && mFC ? mFC * 0.02176 : 0.02176)
    ALPHA = 2.33
    M = mFC
    LENGTH = 0.012
    EFF = 1.0
    XWIDTH = 0.044
    VERBOSE = 1
    YHEIGHT = 0.064;

  Monitor_nD Mon_FermiOutdT AT (0, 0, +0.06 + 0.001) RELATIVE FermiPos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    XWIDTH = 0.044
    YHEIGHT = 0.064
    BINS = iTOF_CHA_RESOL
