    RESTORE_NEUTRON = 1;

  Arm sample_pos AT (0, 0, LME) RELATIVE mono_out ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    EXTEND {
      vix = vx;
      viy = vy;
      viz = vz;
    };

  Isotropic_Sqw Sample AT (0, 0, 0) RELATIVE sample_pos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    SQW_COH = Sqw_coh
    SQW_INC = Sqw_inc
    RADIUS = radius
    THICKNESS = thickness
    YHEIGHT = 0.055
    P_INTERACT = 0.9
    SPLIT = 10
    EXTEND {
      if (!SCATTERED) ABSORB;
    };

  PSD_monitor_4PI Out AT (0, 0, 0) RELATIVE sample_pos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    FILENAME = "out";

  Monitor_nD M_theta_t_all AT (0, 0, 0) RELATIVE sample_pos ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    XWIDTH = 2.5
    YHEIGHT = 1
    BINS = 100
    OPTIONS = opt1
    RESTORE_NEUTRON = 1;

  Sqw_monitor Detector_nM AT (0, 0, 0) RELATIVE M_theta_t_all ROTATED (0, 0, 0) RELATIVE ABSOLUTE
    QMIN = 0
    QMAX = 6
    EMIN = -20
    EMAX = 20
    NQ = 100
    NE = 100
    FILENAME = "Detector_nM"
    VIX = "vix"
    VIY = "viy"
    VIZ = "viz"
    RADIUS = 1.3
    YHEIGHT = 1;

  // Run parameters
  SET seed = 123456;
  SET ncount = 1e6;
  SET gravity = true;

  // Run the simulation
  RUN;

  // Output results
  printf("Integrated intensity on Mon_SuppInL: %g ± %g (events: %g, ncount: %g, seed: %g)\n", Mon_SuppInL.I, Mon_SuppInL.err, Mon_SuppInL.events, ncount, seed);
  printf("Integrated intensity on Mon_SuppInT: %g ± %g (events: %g, ncount: %g, seed: %g)\n", Mon_SuppInT.I, Mon_SuppInT.err, Mon_SuppInT.events, ncount, seed);
  printf("Integrated intensity on Mon_SuppOutT: %g ± %g (events: %g, ncount: %g, seed: %g)\n", Mon_SuppOutT.I, Mon_SuppOutT.err, Mon_SuppOutT.events, ncount, seed);
  printf("Integrated intensity on Mon_FermiOutdT: %g ± %g (events: %g, ncount: %g, seed: %g)\n", Mon_FermiOutdT.I, Mon_FermiOutdT.err, Mon_FermiOutdT.events, ncount, seed);
  printf("Integrated intensity on MonokMonitor: %g ± %g (events: %g, ncount: %g, seed: %g)\n", MonokMonitor.I, MonokMonitor.err, MonokMonitor.events, ncount, seed);
  printf("Integrated intensity on Mon_SampleInT: %g ± %g (events: %g, ncount: %g, seed: %g)\n", Mon_SampleInT.I, Mon_SampleInT.err, Mon_SampleInT.events, ncount, seed);
  printf("Integrated intensity on Mon_SampleInXY: %g ± %g (events: %g, ncount: %g, seed: %g)\n", Mon_SampleInXY.I, Mon_SampleInXY.err, Mon_SampleInXY.events, ncount, seed);
  printf("Integrated intensity on M_theta_t_all: %g ± %g (events: %g, ncount: %g, seed: %g)\n", M_theta_t_all.I, M_theta_t_all.err, M_theta_t_all.events, ncount, seed);
